-  let mtimeMs: number;
-  try {
-    mtimeMs = statSync(file).mtimeMs;
-  } catch {
-    return true;
-  }
-  const ageMs = now - mtimeMs;
-  return !Number.isFinite(ageMs) || ageMs > staleMs;
-}
